/*
 * 061_LIQI_dti_ingestion.sql
 * DtI / Stichtagsvergleich (UC2) raw feeds and reference tables.
 * Extends the shared liquidity book (060_LIQI_ingestion.sql) - simulated
 * ANUBIS / FRISCO / APEL / SPOT data generated by lcr_data_generator.py.
 */

-- ============================================================
-- RAW FEEDS
-- ============================================================

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_SECURED_FUNDING (
    DEAL_ID VARCHAR(50) NOT NULL COMMENT 'Secured funding deal identifier (SF-<holding> for collateralised borrowing, SF-RR-<entity> for reverse repos).',
    AS_OF_DATE DATE NOT NULL COMMENT 'Snapshot (cut-off) date of the deal.',
    ENTITY_ID VARCHAR(10) NOT NULL COMMENT 'Legal entity of the deal (LE_01..LE_09).',
    TRANSACTION_TYPE VARCHAR(30) NOT NULL COMMENT 'Secured business activity: SNB_REPO (central bank refinancing), GC_POOLING, BILATERAL_REPO, REVERSE_REPO (UC2 6.9 element C).',
    COUNTERPARTY_ID VARCHAR(50) COMMENT 'Counterparty of the deal (FK to LIQI_RAW_TB_COUNTERPARTIES; ISS_SNB for central bank repos).',
    COLLATERAL_HOLDING_ID VARCHAR(50) COMMENT 'Pledged security (FK to LIQI_RAW_TB_HQLA_HOLDINGS.HOLDING_ID); NULL for reverse repos (collateral received).',
    ELIGIBLE_COLLATERAL VARCHAR(100) COMMENT 'Collateral quality generally eligible for this transaction type (WLK categories), shown as text on the DtI securities page.',
    NOMINAL_CHF NUMBER(18,2) COMMENT 'Nominal amount of the deal in CHF.',
    MATURITY_DATE DATE COMMENT 'Maturity of the deal; the pledged security returns to the free collateral pool afterwards.',
    DIRECTION VARCHAR(10) COMMENT 'BORROW = cash received against collateral, LEND = reverse repo (cash given, collateral received).',
    INSERT_TIMESTAMP_UTC TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP() COMMENT 'UTC timestamp when the record was loaded into Snowflake.',
    PRIMARY KEY (DEAL_ID, AS_OF_DATE)
)
CLUSTER BY (AS_OF_DATE)
CHANGE_TRACKING = TRUE
COMMENT = 'Daily snapshot of collateralised business activities (SPOT-like, UC2 6.9 element C): central bank repos, GC pooling, bilateral repos and reverse repos with the pledged security. Determines which securities are encumbered and therefore excluded from the free DtI collateral pool. Loaded from dti_secured_funding_YYYYMMDD.csv via stage LIQI_RAW_ST_DTI_SECURED_FUNDING.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_REPORT_STATUS (
    AS_OF_DATE DATE NOT NULL COMMENT 'Reporting date of the LST / DtI run.',
    ENTITY_ID VARCHAR(10) NOT NULL COMMENT 'Legal entity (LE_01..LE_09).',
    DATA_STATUS VARCHAR(20) NOT NULL COMMENT 'FINAL = run confirmed and locked by the business unit (liq_report_date_lock); PRELIMINARY = provisional data not yet quality assured. The DtI pages hide PRELIMINARY data unless the user includes it (UC2 3.1, AC-2).',
    LOCKED_BY VARCHAR(50) COMMENT 'User or process that locked the run; NULL while PRELIMINARY.',
    LOCKED_AT_UTC TIMESTAMP_NTZ COMMENT 'UTC timestamp of the lock; NULL while PRELIMINARY.',
    INSERT_TIMESTAMP_UTC TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP() COMMENT 'UTC timestamp when the record was loaded; the latest load per AS_OF_DATE x ENTITY_ID wins.',
    PRIMARY KEY (AS_OF_DATE, ENTITY_ID)
)
CHANGE_TRACKING = TRUE
COMMENT = 'Report date lock per entity and reporting date (ANUBIS report button, UC2 3.1). Separates final, quality-assured LST data from preliminary runs. Loaded from dti_report_status.csv via stage LIQI_RAW_ST_DTI_CONTROL.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_GENERATION_RUN (
    RUN_ID VARCHAR(30) NOT NULL COMMENT 'Deterministic id of the generator run (hash of seed, as-of date, window, scenario and customers). Stamped on holdings, deposits and DtI securities.',
    AS_OF_DATE DATE NOT NULL COMMENT 'Latest reporting date of the run; the LCR and DtI pages both open on this date.',
    WINDOW_START DATE COMMENT 'First daily LCR snapshot date of the run.',
    HISTORY_START DATE COMMENT 'First DtI month-end snapshot of the same simulation.',
    SEED NUMBER(10,0) COMMENT 'Random seed of the generator.',
    TARGET_LCR NUMBER(6,2) COMMENT 'BASE LCR (percent) the book is calibrated to on AS_OF_DATE.',
    BOOK_SCALE NUMBER(12,6) COMMENT 'Calibrated scale of the wholesale client book (deposits, contracts).',
    SCENARIO VARCHAR(50) COMMENT 'Showcase scenario file (generators/scenarios/<name>.json).',
    CUSTOMERS NUMBER(10,0) COMMENT 'Number of retail customers linked to the CRM master.',
    GENERATOR_VERSION VARCHAR(20) COMMENT 'Version tag of the liquidity book generator.',
    INSERT_TIMESTAMP_UTC TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP() COMMENT 'UTC timestamp when the run record was loaded; the latest load is the current run.',
    PRIMARY KEY (RUN_ID)
)
CHANGE_TRACKING = TRUE
COMMENT = 'One row per generated and loaded liquidity book (LCR + DtI share one book). Source of the run id and as-of date shown on both liquidity pages and checked by the DATA-LIQ gate. Loaded from generation_run.csv via stage LIQI_RAW_ST_DTI_CONTROL.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_CORRECTIONS (
    CORRECTION_ID VARCHAR(30) NOT NULL COMMENT 'Identifier of the manual correction.',
    AS_OF_DATE DATE NOT NULL COMMENT 'Reporting date the correction applies to.',
    ENTITY_ID VARCHAR(10) NOT NULL COMMENT 'Legal entity (LE_01..LE_09).',
    LST_POSITION VARCHAR(50) NOT NULL COMMENT 'Leaf LST position corrected (FK to LIQI_RAW_TB_DTI_LST_POSITIONS.POSITION_CODE), e.g. POOL_CB_BALANCE for the central bank balance.',
    VALUE_DATE DATE NOT NULL COMMENT 'Projection date on which the correction amount is applied.',
    AMOUNT_CHF NUMBER(18,2) NOT NULL COMMENT 'Correction amount in CHF (signed: negative reduces liquidity).',
    COMMENT VARCHAR(500) COMMENT 'Reason for the correction, shown next to the corrected value.',
    CREATED_BY VARCHAR(50) COMMENT 'User who entered the correction.',
    CREATED_AT_UTC TIMESTAMP_NTZ COMMENT 'UTC timestamp of the correction entry.',
    INSERT_TIMESTAMP_UTC TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP() COMMENT 'UTC timestamp when the record was loaded into Snowflake.',
    PRIMARY KEY (CORRECTION_ID)
)
CHANGE_TRACKING = TRUE
COMMENT = 'Manual corrections on LST position and date level (UC2 6.3, AC-4), e.g. the central bank balance. Included in the DtI projection as separate, flagged lines so corrected and uncorrected values stay traceable. Loaded from dti_corrections.csv via stage LIQI_RAW_ST_DTI_CONTROL; later also maintained by the DtI owner role in the app.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_EVENTS (
    EVENT_ID VARCHAR(20) NOT NULL COMMENT 'Identifier of the DtI showcase event (DTI_01..).',
    EVENT_DATE DATE NOT NULL COMMENT 'Reporting date on which the event is visible in the comparison against the previous date.',
    ENTITY_ID VARCHAR(10) COMMENT 'Legal entity mainly affected.',
    EVENT_TYPE VARCHAR(30) COMMENT 'DEPOSIT_WITHDRAWAL, BUCKET_SHIFT, CORRECTION or PRELIMINARY_DATA.',
    POSITION_ID VARCHAR(50) COMMENT 'Position expected as top driver (deposit account, contract or correction id); ground truth for sqlunit/dti_validation.sql.',
    AMOUNT_CHF NUMBER(18,2) COMMENT 'Nominal size of the event in CHF.',
    DESCRIPTION VARCHAR(500) COMMENT 'Business description shown in the app and used by the agent.',
    INSERT_TIMESTAMP_UTC TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP() COMMENT 'UTC timestamp when the record was loaded; latest load per EVENT_ID wins.'
)
COMMENT = 'Deterministic DtI showcase events (large deposit withdrawal at LE_02, bucket shift, correction, preliminary run). Ground truth for DtI tests and annotations. Loaded from dti_events.csv via stage LIQI_RAW_ST_DTI_CONTROL.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_PLANNING (
    AS_OF_DATE DATE NOT NULL COMMENT 'Reporting date of the planning snapshot.',
    ENTITY_ID VARCHAR(10) NOT NULL COMMENT 'Legal entity (LE_01..LE_09).',
    PLAN_TYPE VARCHAR(20) NOT NULL COMMENT 'NEW_LENDING (planned new loans, outflow) or FUNDING_PLAN (planned issuance, inflow).',
    VALUE_DATE DATE NOT NULL COMMENT 'Projection date of the planned cash flow.',
    AMOUNT_CHF NUMBER(18,2) NOT NULL COMMENT 'Planned cash flow in CHF (signed: negative = outflow).',
    INSERT_TIMESTAMP_UTC TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP() COMMENT 'UTC timestamp when the record was loaded into Snowflake.',
    PRIMARY KEY (AS_OF_DATE, ENTITY_ID, PLAN_TYPE, VALUE_DATE)
)
CHANGE_TRACKING = TRUE
COMMENT = 'Planning positions without deal level data (Kreditneugeschaeft, Fundingplanung; UC2 6.3 further information). Shown aggregated in the DtI projection and never drillable. Loaded from dti_planning.csv via stage LIQI_RAW_ST_DTI_CONTROL.';

DEFINE STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_SECURED_FUNDING
    DIRECTORY = (ENABLE = TRUE AUTO_REFRESH = TRUE)
    COMMENT = 'Internal landing stage for daily secured funding snapshots (dti_secured_funding_YYYYMMDD.csv). Monitored by stream LIQI_RAW_SM_DTI_SECURED_FUNDING_FILES and loaded by task LIQI_RAW_TK_LOAD_DTI_SECURED_FUNDING.';

DEFINE STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_CONTROL
    DIRECTORY = (ENABLE = TRUE AUTO_REFRESH = TRUE)
    COMMENT = 'Internal landing stage for the DtI control files: dti_report_status.csv, dti_corrections.csv, dti_events.csv and dti_planning.csv. Monitored by stream LIQI_RAW_SM_DTI_CONTROL_FILES.';

DEFINE STREAM {{ db }}.{{ rep_raw }}.LIQI_RAW_SM_DTI_SECURED_FUNDING_FILES
    ON STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_SECURED_FUNDING
    COMMENT = 'Monitors LIQI_RAW_ST_DTI_SECURED_FUNDING for new files; triggers LIQI_RAW_TK_LOAD_DTI_SECURED_FUNDING.';

DEFINE STREAM {{ db }}.{{ rep_raw }}.LIQI_RAW_SM_DTI_CONTROL_FILES
    ON STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_CONTROL
    COMMENT = 'Monitors LIQI_RAW_ST_DTI_CONTROL for new files; consumed by LIQI_RAW_TK_LOAD_DTI_REPORT_STATUS only (one stream per consuming task).';

DEFINE STREAM {{ db }}.{{ rep_raw }}.LIQI_RAW_SM_DTI_CORRECTION_FILES
    ON STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_CONTROL
    COMMENT = 'Monitors LIQI_RAW_ST_DTI_CONTROL for new files; consumed by LIQI_RAW_TK_LOAD_DTI_CORRECTIONS only (one stream per consuming task).';

DEFINE STREAM {{ db }}.{{ rep_raw }}.LIQI_RAW_SM_DTI_EVENT_FILES
    ON STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_CONTROL
    COMMENT = 'Monitors LIQI_RAW_ST_DTI_CONTROL for new files; consumed by LIQI_RAW_TK_LOAD_DTI_EVENTS only (one stream per consuming task).';

DEFINE STREAM {{ db }}.{{ rep_raw }}.LIQI_RAW_SM_DTI_PLANNING_FILES
    ON STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_CONTROL
    COMMENT = 'Monitors LIQI_RAW_ST_DTI_CONTROL for new files; consumed by LIQI_RAW_TK_LOAD_DTI_PLANNING only (one stream per consuming task).';

DEFINE STREAM {{ db }}.{{ rep_raw }}.LIQI_RAW_SM_GENERATION_RUN_FILES
    ON STAGE {{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_CONTROL
    COMMENT = 'Monitors LIQI_RAW_ST_DTI_CONTROL for new files; consumed by LIQI_RAW_TK_LOAD_GENERATION_RUN only (one stream per consuming task).';

DEFINE TASK {{ db }}.{{ rep_raw }}.LIQI_RAW_TK_LOAD_DTI_SECURED_FUNDING
    USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
    SCHEDULE = '60 MINUTE'
    COMMENT = 'Hourly load of secured funding snapshots into LIQI_RAW_TB_DTI_SECURED_FUNDING when stream LIQI_RAW_SM_DTI_SECURED_FUNDING_FILES has data (ON_ERROR=CONTINUE).'
    WHEN SYSTEM$STREAM_HAS_DATA('{{ db }}.{{ rep_raw }}.LIQI_RAW_SM_DTI_SECURED_FUNDING_FILES')
    STARTED
AS
    EXECUTE IMMEDIATE $$
    BEGIN
        COPY INTO {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_SECURED_FUNDING (
            DEAL_ID, AS_OF_DATE, ENTITY_ID, TRANSACTION_TYPE, COUNTERPARTY_ID, COLLATERAL_HOLDING_ID,
            ELIGIBLE_COLLATERAL, NOMINAL_CHF, MATURITY_DATE, DIRECTION
        )
        FROM @{{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_SECURED_FUNDING
        FILE_FORMAT = (TYPE = 'CSV' FIELD_OPTIONALLY_ENCLOSED_BY = '"' SKIP_HEADER = 1 FIELD_DELIMITER = ','
                       TRIM_SPACE = TRUE NULL_IF = ('NULL', 'null', '') ERROR_ON_COLUMN_COUNT_MISMATCH = FALSE)
        PATTERN = '.*dti_secured_funding_.*\\.csv'
        ON_ERROR = 'CONTINUE';
        -- consume the file stream (offset only): it is empty again and does not go stale
        CREATE OR REPLACE TEMPORARY TABLE STREAM_ADVANCE AS SELECT RELATIVE_PATH FROM {{ db }}.{{ rep_raw }}.LIQI_RAW_SM_DTI_SECURED_FUNDING_FILES WHERE 0 = 1;
    END;
    $$;

DEFINE TASK {{ db }}.{{ rep_raw }}.LIQI_RAW_TK_CLEANUP_AFTER_LOAD_DTI_SECURED_FUNDING
    USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
    COMMENT = 'Automated stage cleanup AFTER the secured funding load. Keeps the last 5 files in LIQI_RAW_ST_DTI_SECURED_FUNDING.'
    AFTER {{ db }}.{{ rep_raw }}.LIQI_RAW_TK_LOAD_DTI_SECURED_FUNDING
    STARTED
AS
    CALL LIQI_RAW_SP_CLEANUP_STAGE_KEEP_LAST_N('{{ db }}.{{ rep_raw }}.LIQI_RAW_ST_DTI_SECURED_FUNDING', 5);

