-- ============================================================
-- REFERENCE TABLES (seeded by post_deploy.sql)
-- ============================================================

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_ENTITIES (
    ENTITY_ID VARCHAR(10) NOT NULL COMMENT 'Legal entity code LE_01..LE_09.',
    ENTITY_NAME VARCHAR(50) NOT NULL COMMENT 'Display name (Legal Entity 1..9). Group = sum of the selected entities, computed in the app.',
    SORT_ORDER INTEGER NOT NULL COMMENT 'Fixed display order of the entities on all DtI pages.',
    IS_DEFAULT BOOLEAN NOT NULL COMMENT 'TRUE for the entities selected by default (LE_01..LE_03).',
    CB_BALANCE_SHARE NUMBER(6,4) NOT NULL COMMENT 'Share of the centrally booked central bank and vault cash allocated to the entity in the DtI collateral pool (shares sum to 1).',
    PRIMARY KEY (ENTITY_ID)
)
COMMENT = 'Legal entities of the DtI comparison (generic names, UC2 6.1/6.2 entity filter). Seeded by post_deploy.sql.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_LST_POSITIONS (
    POSITION_CODE VARCHAR(50) NOT NULL COMMENT 'LST position code (e.g. OUT_DEP_RETAIL).',
    POSITION_NAME VARCHAR(100) NOT NULL COMMENT 'Display name of the position.',
    PARENT_CODE VARCHAR(50) COMMENT 'Parent position in the LST tree; NULL for Level I positions.',
    LEVEL_NO INTEGER NOT NULL COMMENT 'Hierarchy level 1..4 (Level I = Collateral Pool, Deterministic Cash Flows, Inflows, Outflows).',
    SORT_ORDER INTEGER NOT NULL COMMENT 'Display order within the parent.',
    IS_LEAF BOOLEAN NOT NULL COMMENT 'TRUE for positions that carry values; parents are sums of their children.',
    IS_DRILLABLE BOOLEAN NOT NULL COMMENT 'FALSE for aggregate positions without deal level data (e.g. new lending, funding plan); shown aggregated only.',
    IS_DETERMINISTIC BOOLEAN NOT NULL COMMENT 'TRUE when base and stressed values are identical (deterministic cash flows).',
    PRIMARY KEY (POSITION_CODE)
)
COMMENT = 'LST position scheme (Level I-IV, UC2 6.3 and appendix): the tree along which all DtI deltas are shown and drilled down. Seeded by post_deploy.sql.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_LST_ASSIGNMENT (
    SOURCE_SYSTEM VARCHAR(20) NOT NULL COMMENT 'Source feed: CONTRACTS, CASHFLOWS, DEPOSITS, HOLDINGS or PLANNING.',
    PRODUCT_TYPE VARCHAR(50) NOT NULL COMMENT 'Source product / deposit / asset type, or * for any.',
    COUNTERPARTY_SECTOR VARCHAR(30) NOT NULL COMMENT 'Counterparty sector or * for any.',
    FLOW_KIND VARCHAR(20) NOT NULL COMMENT 'CONTRACTUAL (deterministic cash flow), RUNOFF (modelled outflow), DRAWDOWN (modelled facility outflow), INFLOW (modelled inflow) or POOL (collateral pool).',
    POSITION_CODE VARCHAR(50) NOT NULL COMMENT 'Leaf LST position the flow is assigned to (FK to LIQI_RAW_TB_DTI_LST_POSITIONS).',
    PRODUCT_CLUSTER VARCHAR(30) COMMENT 'Product cluster for the product group pages (FK to LIQI_RAW_TB_DTI_PRODUCT_CLUSTERS).',
    PRIMARY KEY (SOURCE_SYSTEM, PRODUCT_TYPE, COUNTERPARTY_SECTOR, FLOW_KIND)
)
COMMENT = 'Assignment rules from source positions and flows to LST positions and product clusters (simplified one-stage version of the FRISCO query selection + ANUBIS assignment, UC2 3.2). Changing a rule needs no code change. Seeded by post_deploy.sql.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_APPLICATIONS (
    APPLICATION_ID VARCHAR(10) NOT NULL COMMENT 'Application code (HYP, KRE, GEL, EIN, DER).',
    APPLICATION_NAME VARCHAR(100) NOT NULL COMMENT 'Display name of the application.',
    SORT_ORDER INTEGER NOT NULL COMMENT 'Column order on the application page.',
    PRIMARY KEY (APPLICATION_ID)
)
COMMENT = 'Applications delivering fixed cash flows (Fixe Ablaeufe) for the DtI application page (UC2 6.4). Seeded by post_deploy.sql.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_PRODUCT_CLUSTERS (
    PRODUCT_CLUSTER VARCHAR(30) NOT NULL COMMENT 'Product cluster code (PC_..).',
    CLUSTER_NAME VARCHAR(100) NOT NULL COMMENT 'Display name of the cluster.',
    PRODUCT_GROUP VARCHAR(50) NOT NULL COMMENT 'Product group the cluster belongs to (Gesamtposition > Produktgruppe > Produktcluster, UC2 6.5).',
    SORT_ORDER INTEGER NOT NULL COMMENT 'Display order of the row on the DtI pages and in filter lists.',
    PRIMARY KEY (PRODUCT_CLUSTER)
)
COMMENT = 'Product groups and clusters for the DtI product pages (UC2 6.5/6.6); flexible, manually defined grouping. Seeded by post_deploy.sql.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_WLK_CLUSTERS (
    WLK_CLUSTER VARCHAR(5) NOT NULL COMMENT 'Internal collateral cluster code I..XIb.',
    CLUSTER_NAME VARCHAR(100) NOT NULL COMMENT 'Descriptive cluster name (UC2 review note: add explicit names).',
    HAIRCUT NUMBER(5,4) NOT NULL COMMENT 'Default haircut of the cluster in the collateral pool.',
    HQLA_CATEGORY VARCHAR(10) COMMENT 'Regulatory HQLA category of typical assets (L1, L2A, L2B, NONE).',
    SORT_ORDER INTEGER NOT NULL COMMENT 'Display order of the row on the DtI pages and in filter lists.',
    PRIMARY KEY (WLK_CLUSTER)
)
COMMENT = 'Internal collateral clusters (WLK) with names, haircuts and HQLA category (UC2 6.8-6.10). Seeded by post_deploy.sql.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_BUCKETS (
    BUCKET_CODE VARCHAR(10) NOT NULL COMMENT 'Bucket code W1, W2, W3, M01..M12, GT12M.',
    BUCKET_NAME VARCHAR(30) NOT NULL COMMENT 'Display name (1 week, 2 weeks, 3 weeks, 1 month .. 12 months, > 12 months).',
    OFFSET_UNIT VARCHAR(5) NOT NULL COMMENT 'Unit of the upper bound: DAY or MONTH, applied relative to each reporting date.',
    OFFSET_VALUE INTEGER COMMENT 'Upper bound relative to the reporting date (e.g. 7 DAY, 2 MONTH); NULL for the open-ended last bucket.',
    SORT_ORDER INTEGER NOT NULL COMMENT 'Display order of the row on the DtI pages and in filter lists.',
    PRIMARY KEY (BUCKET_CODE)
)
COMMENT = 'Time buckets of the DtI comparison (UC2 6.3): each bucket is defined relative to its own reporting date, so the same bucket covers different calendar days for the reference and the comparison date. Seeded by post_deploy.sql.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_HOLIDAYS (
    HOLIDAY_DATE DATE NOT NULL COMMENT 'Bank holiday (Zurich business calendar).',
    HOLIDAY_NAME VARCHAR(50) NOT NULL COMMENT 'Name of the holiday.',
    PRIMARY KEY (HOLIDAY_DATE)
)
COMMENT = 'Bank holidays of the Zurich business calendar used by the DtI daily view (business days = Mon-Fri excluding these dates). Seeded by post_deploy.sql; reseeding switches the calendar.';

DEFINE TABLE {{ db }}.{{ rep_raw }}.LIQI_RAW_TB_DTI_LIMITS (
    ENTITY_ID VARCHAR(10) NOT NULL COMMENT 'Legal entity (LE_01..LE_09) or GROUP.',
    BUCKET_CODE VARCHAR(10) NOT NULL COMMENT 'DtI bucket (FK to LIQI_RAW_TB_DTI_BUCKETS) or * for all buckets.',
    COMMENT_THRESHOLD_CHF NUMBER(18,2) NOT NULL COMMENT 'Commenting threshold: deltas with an absolute value at or above it are highlighted (orange) on the summary page (UC2 6.1).',
    PRIMARY KEY (ENTITY_ID, BUCKET_CODE)
)
COMMENT = 'Commenting thresholds per entity and bucket for the DtI comparison (manual inputs, UC2 6.1/6.10). Seeded by post_deploy.sql; maintained by the DtI owner role.';
